description:
Each frame, decide which input the game may act on. Write

```cpp
struct Frame
{
    bool wantCaptureMouse;
    bool wantCaptureKeyboard;
    bool mouseClicked;
    std::vector<char> keys;       // keys pressed this frame
};

struct GameInput { bool shoot{ false }; std::string moves; };

GameInput gameInput(const Frame& f);
```

- The game shoots only if the mouse was clicked **and** ImGui does not want the mouse.
- The game moves for each of `w`, `a`, `s`, `d` in `keys`, in order (other keys are ignored), only if ImGui does not want the keyboard. `moves` is those letters as a string.

starter.solution.cpp:
#include <string>
#include <vector>

struct Frame { bool wantCaptureMouse; bool wantCaptureKeyboard; bool mouseClicked; std::vector<char> keys; };
struct GameInput { bool shoot{ false }; std::string moves; };

GameInput gameInput(const Frame& f) { return {}; }

solution.solution.cpp:
#include <string>
#include <vector>

struct Frame { bool wantCaptureMouse; bool wantCaptureKeyboard; bool mouseClicked; std::vector<char> keys; };
struct GameInput { bool shoot{ false }; std::string moves; };

GameInput gameInput(const Frame& f)
{
    GameInput g;
    g.shoot = f.mouseClicked && !f.wantCaptureMouse;
    if (!f.wantCaptureKeyboard)
        for (char k : f.keys) if (k == 'w' || k == 'a' || k == 's' || k == 'd') g.moves += k;
    return g;
}

unitTests:
TEST("nothing captured") { const auto g = gameInput({ false, false, true, { 'w', 'x', 'd' } }); CHECK(g.shoot); CHECK_EQ(g.moves, std::string("wd")); }
TEST("typing in a text field") { const auto g = gameInput({ false, true, false, { 'w', 'a' } }); CHECK_EQ(g.moves, std::string("")); }
TEST("clicking a button") { const auto g = gameInput({ true, false, true, { 's' } }); CHECK(!g.shoot); CHECK_EQ(g.moves, std::string("s")); }
TEST("no click") { CHECK(!gameInput({ false, false, false, {} }).shoot); }

